
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ak13_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ak13", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.358541917884740e+00, -4.279251937209620e+00, -4.168470638842791e+00, -4.015698196857235e+00, -3.809003025720559e+00, -3.537121673601586e+00, -3.194272555305891e+00, -2.789053308883342e+00, -2.356275794711314e+00, -1.946722478868252e+00, -1.437310113131405e+00, -7.438633267317816e-01, -6.056660122894536e-01, -5.194341334796397e-01, -4.205984959370214e-01, -3.624092098874366e-01, -4.109662751657773e-01, -6.297080362797242e-01, -1.087175317054511e+00, -1.856493227469284e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


